    morainePackage
  ];

  home.sessionPath = [
    "$HOME/.local/bin"
  ];

  home.file.${moraineConfigRelative}.text = moraineConfig;

  home.activation.removeLegacyAoeUnits = lib.hm.dag.entryBefore [ "writeBoundary" ] ''
    rm -f \
      "$HOME/.config/systemd/user/aoe-serve.service" \
      "$HOME/.config/systemd/user/aoe-lan-proxy.service" \
      "$HOME/.config/systemd/user/aoe-lan-proxy.socket"
  '';

  systemd.user.startServices = "sd-switch";

  # Upstream owns installation, readiness, migrations, and child startup. The
  # foreground wrapper keeps this unit alive only while that complete stack is
  # healthy, so one restart policy accurately represents the operator surface.
  systemd.user.services.moraine = {
    Unit = {
      Description = "Workstation-local Moraine producer";
      X-Restart-Triggers = [ config.home.file.${moraineConfigRelative}.source ];
    };

    Service = {
      Type = "simple";
      ExecStart = "${moraineService}/bin/moraine-service ${morainePackage}/bin/moraine ${moraineConfigPath}";
      ExecStop = "${moraineControl} down";
      Restart = "on-failure";
      RestartSec = 5;
    };

    Install.WantedBy = [ "default.target" ];
  };

  # installPackages is what creates the profile this handoff reads from. Ordered
  # only after reloadSystemd, the handoff ran while ~/.nix-profile was still a
  # dangling symlink, so every home.packages tool the updater needs — npm, jq —
  # was missing and activation died on whichever one it probed first.
  home.activation.bootstrapAgentTools =
    lib.hm.dag.entryAfter [ "reloadSystemd" "installPackages" ] ''
      # Activation runs with a curated store-only PATH holding just coreutils and
      # friends, so system directories are absent. The updater's remaining host
      # tools — flock for its lock, curl for the AoE release check, unzip and find
      # for the Bun archive — come from the store rather than from whatever the
      # host happens to install.
      #
      # The system directories go last, after everything the store supplies, for
      # systemctl alone: the updater restarts a unit in this host's user session,
      # so it needs that session's own systemd rather than a store copy of one.
      export PATH="$HOME/.local/bin:${config.home.profileDirectory}/bin:${updaterHostTools}:$PATH:/usr/local/bin:/usr/bin:/bin"

      # bun is listed because the updater owns it: nixpkgs lags Bun releases badly
      # enough that a harness engine floor can outrun it, so a switch that finds
      # no bun must hand off rather than leave the harnesses without a runtime.
      _agent_tools_missing=false
      for _agent_tool in \
        aoe bun codex claude pi opencode omp codex-acp claude-agent-acp pi-acp; do
        if ! command -v "$_agent_tool" >/dev/null 2>&1; then
          _agent_tools_missing=true
          break
        fi
      done

      if [ "$_agent_tools_missing" = true ]; then
        command -v aoe >/dev/null 2>&1 \
          || { echo "Agent-tool bootstrap requires chezmoi to install AoE first" >&2; exit 1; }
        command -v update-agent-tools >/dev/null 2>&1 \
          || { echo "Agent-tool bootstrap requires the dotfiles updater" >&2; exit 1; }
        update-agent-tools --yes
      fi
    '';

  systemd.user.services.aoe-serve = {
    Unit = {
      Description = "Agent of Empires web dashboard";
      After = [ "default.target" ];
      # aoe-serve binds 127.0.0.1:4000; the portal reaches it only through the
      # socket-activated proxy on 4001. Starting the app without the socket leaves
      # the origin port unbound, which looks like an application fault from the
      # portal side. Wants, not Requires: the app is still useful locally if the
      # socket fails, and Wants adds no ordering to deadlock against the proxy's
      # own Requires=aoe-serve.service.
      Wants = [ "aoe-lan-proxy.socket" ];
    };

    Service = {
      Type = "simple";
      Environment = "PATH=%h/.local/bin:%h/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
      ExecStart = "/usr/bin/env aoe serve --host 127.0.0.1 --port 4000 --no-auth --behind-proxy --allowed-host aoe.local.faviann.com";
      Restart = "on-failure";
      RestartSec = 5;
    };

    Install.WantedBy = [ "default.target" ];
  };

  systemd.user.services.aoe-lan-proxy = {
    Unit = {
      Description = "AoE LAN proxy";
      Requires = [ "aoe-serve.service" ];
      After = [ "aoe-serve.service" ];
    };

    Service.ExecStart = "/lib/systemd/systemd-socket-proxyd 127.0.0.1:4000";
  };

  systemd.user.sockets.aoe-lan-proxy = {
    Unit.Description = "AoE LAN proxy socket";

    Wants=collie-origin-forwarder.socket
  '';

  systemd.user.services.hermes-gateway = {
    Unit = {
      Description = "Hermes Agent gateway";
      After = [ "default.target" ];
    };
    Service = {
      Type = "simple";
      Environment = "PATH=%h/.local/bin:%h/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
      ExecStart = "/usr/bin/env hermes gateway run";
      Restart = "on-failure";
      RestartSec = 10;
    };
    Install.WantedBy = [ "default.target" ];
  };

  systemd.user.services.hermes-dashboard = {
    Unit = {
      Description = "Hermes Agent dashboard";
      Requires = [ "hermes-gateway.service" ];
      After = [ "default.target" "hermes-gateway.service" ];
    };
    Service = {
      Type = "simple";
      Environment = "PATH=%h/.local/bin:%h/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
      ExecStart = "/usr/bin/env hermes dashboard --host 0.0.0.0 --port 9119 --no-open --insecure";
      Restart = "on-failure";
      RestartSec = 10;
    };
    Install.WantedBy = [ "default.target" ];
  };

  # This is the final supervised shape, staged without Install.WantedBy or an
  # activation hook so applying Home Manager cannot cut over the detached server.
  systemd.user.services.herdr.Service = {
    Type = "simple";
    Environment =
      "PATH=/home/faviann/.local/bin:/home/faviann/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
    ExecStart = "/home/faviann/.local/bin/herdr server";
    Restart = "on-failure";
    RestartSec = 5;
    WorkingDirectory = "/home/faviann";
  };
  programs.openclaw = {
    enable = true;
    stateDir = "${config.home.homeDirectory}/.openclaw";
    systemd.enable = true;
    systemd.unitName = "openclaw-gateway";
  };

  # The nix-openclaw module writes openclaw.json as a read-only nix-store symlink,
  # which prevents openclaw from persisting runtime state (auth tokens, model choices, etc.).
  # These two hooks bracket nix-openclaw's generated config link:
  # save it before Home Manager writes links, restore it after openclawConfigFiles.
  home.activation.openclawSaveConfig = lib.hm.dag.entryBefore [ "writeBoundary" ] ''
    _oc_config="${config.programs.openclaw.stateDir}/openclaw.json"
    _oc_saved="${config.programs.openclaw.stateDir}/openclaw.json.pre-hm"
    if [ -f "$_oc_config" ] && [ ! -L "$_oc_config" ]; then
      cp "$_oc_config" "$_oc_saved"
        builtins.toJSON {
          dotnetSdkPackage =
            let
              package = builtins.head (
                builtins.filter
                  (package: (package.pname or package.name) == "dotnet-sdk-wrapped")
                  workstationHomeConfiguration.config.home.packages
              );
            in
            {
              pname = package.pname or package.name;
              inherit (package) version;
            };
          moraineRelease = {
            inherit (morainePackage) version;
            hash = morainePackage.src.outputHash;
            source = morainePackage.src.url;
            storePath = "${morainePackage}";
            hasReleasePassthru = morainePackage.passthru ? release;
          };
          moraineConfig = builtins.fromTOML (builtins.unsafeDiscardStringContext (
            workstationHomeConfiguration.config.home.file.".moraine/config.toml".text
          ));
          moraineServiceTopology =
            let
              services = workstationHomeConfiguration.config.systemd.user.services;
            in
            {
              names = builtins.filter
                (name: builtins.match "moraine.*" name != null)
                (builtins.attrNames services);
              service = services.moraine;
            };
          moraineCodexBoundary = {
            managesConfig = workstationHomeConfiguration.config.home.file ? ".codex/config.toml";
            hasRegistrationActivation =
              workstationHomeConfiguration.config.home.activation ? configureMoraineCodexMcp;
          };
          collieOriginSocket =
            workstationHomeConfiguration.config.systemd.user.sockets.collie-origin-forwarder;
          collieOriginService =
            workstationHomeConfiguration.config.systemd.user.services.collie-origin-forwarder;
          aoeLanProxySocket = workstationHomeConfiguration.config.systemd.user.sockets.aoe-lan-proxy;
          aoeLanProxyService = workstationHomeConfiguration.config.systemd.user.services.aoe-lan-proxy;
          aoeServeService = workstationHomeConfiguration.config.systemd.user.services.aoe-serve;
          herdrService = workstationHomeConfiguration.config.systemd.user.services.herdr;
          workstationActivation = builtins.mapAttrs (
            _: entry: entry.data or ""
          ) workstationHomeConfiguration.config.home.activation;
          collieServiceDropIn =
            workstationHomeConfiguration.config.xdg.configFile
            ."systemd/user/collie.service.d/10-origin-forwarder.conf".text;
        }
      );
      shellcheckSource = nixpkgs.lib.fileset.toSource {
        root = ./.;
        fileset = nixpkgs.lib.fileset.unions [
          ./.chezmoiscripts
          ./dot_bash_profile.tmpl
          ./dot_bashrc.tmpl
          ./dot_local/bin/executable_update-agent-tools
          ./dot_local/bin/executable_workstation-login
          ./dot_local/bin/executable_workstation-update
          ./scripts/moraine-service
          ./scripts/run-shellcheck
          ./scripts/run-tests
Eligible interactive SSH logins run a synchronous, non-mutating freshness
check from the dotfiles-managed Bash login profile. Dotfiles and agent-tool
sources cache successful checks for 24 hours and retry failed source checks
after one hour; their cache ages are independent. Local blockers and incomplete
maintenance are evaluated on every eligible login. Healthy or not-yet-due state
is silent. Available updates and retryable maintenance produce one combined
notice with exactly one `Run: workstation-update` action. A local blocker
instead says that maintenance is blocked and must be resolved before the
command is run. A hard 15-second deadline bounds the check, and failure or
timeout never prevents the shell from opening.

Login never installs updates. There is no workstation-side background timer or
scheduler, and local shells, remote commands, and non-interactive shells do not
run the login check. Workstations without the completed setup marker also skip
it. Each eligible SSH login warns when maintenance is actionable; healthy state
remains silent. The login profile deliberately does not source `.bashrc`, so
unrelated interactive-shell configuration is not pulled into the login
boundary.

## Workstation herdr

[herdr](https://herdr.dev) is a terminal agent multiplexer, installed for
evaluation alongside AoE. It is not an AoE replacement: AoE serves conversations
over HTTP, while herdr is a TUI.

- Install: `.chezmoiscripts/run_once_install-herdr.sh.tmpl` uses the upstream
  installer until there is a clean Nix package path. herdr is packaged in
  nixpkgs, but not in the pinned nixpkgs revision.
- Updates: herdr is deliberately outside the `workstation-update` managed unit.
  It self-updates through `herdr update`, run by hand. That command refuses to
  run from inside a herdr pane; detach from the session first.
- Configuration: `~/.config/herdr/config.toml` is optional and unmanaged. herdr
  writes to it itself, so chezmoi does not own it.
- Supervision staging: Home Manager installs the final foreground
  `herdr.service` shape, but the unit has no user-target enablement and applying
  the configuration does not start it. Activation is deferred to the scheduled
  cutover because server shutdown ends pane processes. Until that cutover, the
  existing detached server and its active panes remain in place.

The manual, loopback-only Collie evaluation that uses herdr is documented in
the [Collie pilot runbook](docs/collie-pilot-runbook.md). Collie's plugin,
configuration, state, and generated service remain outside dotfiles ownership.
